```javascript
function isValid(s) {
  const stack = [];
  const pairs = { '(': ')', '{': '}', '[': ']' };
  for (let char of s) {
    if (pairs[char]) stack.push(char);
    else if (pairs[stack.pop()] !== char) return false;
  }
  return stack.length === 0;
}
```
O(N) Time, O(N) Space.
